<?php

namespace App\Services;

use Illuminate\Support\Facades\Storage;
use Symfony\Component\HttpFoundation\StreamedResponse;

/** Sends a file kept on the private disk. Callers must have checked that the user may open it. */
class PrivateFileResponder
{
    public function respond(?string $path, ?string $downloadName = null): StreamedResponse
    {
        $disk = Storage::disk('local');

        // A path is always generated by the application; one that climbs out of the folder is refused outright.
        abort_if(blank($path) || str_contains($path, '..') || ! $disk->exists($path), 404);

        return $disk->response(
            $path,
            $downloadName ?: basename($path),
            ['Cache-Control' => 'private, max-age=0, must-revalidate'],
            'inline',
        );
    }
}
